const migrationAbortedMessage = "migration to RBAC has aborted because of the backend error, restart teleport to try again"

// migrateOSS performs migration to enable role-based access controls
// for open source users. It downgrades the existing admin role and assigns
// users and trusted cluster mappings to that role.
// this function can be called multiple times
// DELETE IN(7.0)
func migrateOSS(ctx context.Context, asrv *Server) error {
	if modules.GetModules().BuildType() != modules.BuildOSS {
		return nil
	}
	adminRole, err := asrv.GetRole(teleport.AdminRoleName)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}
	if _, migrated := adminRole.GetMetadata().Labels[teleport.OSSMigratedV6]; migrated {
		log.Debug("OSS admin role was already migrated; skipping migration.")
		return nil
	}
	role := services.NewDowngradedOSSAdminRole()
	log.Infof("Enabling RBAC in OSS Teleport. Migrating users, roles and trusted clusters.")
	migratedUsers, err := migrateOSSUsers(ctx, role, asrv)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	migratedTcs, err := migrateOSSTrustedClusters(ctx, role, asrv)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	migratedConns, err := migrateOSSGithubConns(ctx, role, asrv)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	// Mark the admin role as migrated after the other updates succeed, so a
	// failed update can be retried on the next start.
	if err := asrv.UpsertRole(ctx, role); err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}
	log.Infof("Migration completed. Downgraded admin role and updated %v users, %v trusted clusters and %v Github connectors.",
		migratedUsers, migratedTcs, migratedConns)

	return nil
}

const remoteWildcardPattern = "^.+$"

// migrateOSSTrustedClusters updates role mappings in trusted clusters
// OSS Trusted clusters had no explicit mapping from remote roles, to local roles.
// Map all remote roles to the local admin role.
func migrateOSSTrustedClusters(ctx context.Context, role types.Role, asrv *Server) (int, error) {
	migratedTcs := 0
	tcs, err := asrv.GetTrustedClusters()
	if err != nil {
		return migratedTcs, trace.Wrap(err, migrationAbortedMessage)
	}

	for _, tc := range tcs {
		meta := tc.GetMetadata()
		_, migrated := meta.Labels[teleport.OSSMigratedV6]
		roleMap := types.RoleMap{{Remote: remoteWildcardPattern, Local: []string{role.GetName()}}}
		updatedMap, replaced := replaceOSSUserRoleMap(tc.GetRoleMap(), role.GetName())
		updated := false
		if !migrated || replaced {
			if !migrated {
				updatedMap = roleMap
			}
			setLabels(&meta.Labels, teleport.OSSMigratedV6, types.True)
			tc.SetRoleMap(updatedMap)
			tc.SetMetadata(meta)
			if _, err := asrv.Presence.UpsertTrustedCluster(ctx, tc); err != nil {
				return migratedTcs, trace.Wrap(err, migrationAbortedMessage)
			}
			updated = true
		}
		for _, catype := range []services.CertAuthType{services.UserCA, services.HostCA} {
			ca, err := asrv.GetCertAuthority(services.CertAuthID{Type: catype, DomainName: tc.GetName()}, true)
			if err != nil {
				return migratedTcs, trace.Wrap(err, migrationAbortedMessage)
			}
			meta := ca.GetMetadata()
			_, migrated := meta.Labels[teleport.OSSMigratedV6]
			updatedMap, replaced := replaceOSSUserRoleMap(ca.GetRoleMap(), role.GetName())
			if migrated && !replaced {
				continue
			}
			if !migrated {
				updatedMap = roleMap
			}
			setLabels(&meta.Labels, teleport.OSSMigratedV6, types.True)
			ca.SetRoleMap(updatedMap)
			ca.SetMetadata(meta)
			err = asrv.UpsertCertAuthority(ca)
			if err != nil {
				return migratedTcs, trace.Wrap(err, migrationAbortedMessage)
			}
			updated = true
		}
		if updated {
			migratedTcs++
		}
	}
	return migratedTcs, nil
}

// replaceOSSUserRoleMap replaces mappings left by the earlier OSS migration
// while preserving any other mappings added since then.
func replaceOSSUserRoleMap(roleMap types.RoleMap, replacement string) (types.RoleMap, bool) {
	updatedMap := make(types.RoleMap, len(roleMap))
	replaced := false
	for i, mapping := range roleMap {
		updatedMap[i] = mapping
		updatedRoles, changed := replaceOSSUserRole(mapping.Local, replacement)
		if changed {
			updatedMap[i].Local = updatedRoles
			replaced = true
		}
	}
	return updatedMap, replaced
}

// migrateOSSUsers explicitly assigns OSS users to the downgraded admin role.
// Users left on ossuser by an earlier migration are moved to admin as well.
func migrateOSSUsers(ctx context.Context, role types.Role, asrv *Server) (int, error) {
	migratedUsers := 0
	users, err := asrv.GetUsers(true)
	if err != nil {
		return migratedUsers, trace.Wrap(err, migrationAbortedMessage)
	}

	for _, user := range users {
		meta := user.GetMetadata()
		_, migrated := meta.Labels[teleport.OSSMigratedV6]
		if migrated {
			updatedRoles, replaced := replaceOSSUserRole(user.GetRoles(), role.GetName())
			if !replaced {
				continue
			}
			user.SetRoles(updatedRoles)
		} else {
			user.SetRoles([]string{role.GetName()})
		}
		setLabels(&meta.Labels, teleport.OSSMigratedV6, types.True)
		user.SetMetadata(meta)
		if err := asrv.UpsertUser(user); err != nil {
			return migratedUsers, trace.Wrap(err, migrationAbortedMessage)
		}
		migratedUsers++
	}

	return migratedUsers, nil
}

func replaceOSSUserRole(roles []string, replacement string) ([]string, bool) {
	updatedRoles := make([]string, len(roles))
	replaced := false
	for i, role := range roles {
		if role == teleport.OSSUserRoleName {
			role = replacement
			replaced = true
		}
		updatedRoles[i] = role
	}
	if replaced {
		updatedRoles = utils.Deduplicate(updatedRoles)
	}
	return updatedRoles, replaced
}

func setLabels(v *map[string]string, key, val string) {
	if *v == nil {
		*v = map[string]string{
			key: val,
		}
		return
	}
	(*v)[key] = val
}

